import{U as e,W as t,nt as n,t as r}from"./chunks/framework.CPHJXLir.js";var i=JSON.parse(`{"title":"Using Events to Extend Existing Business Logic","description":"","frontmatter":{},"headers":[],"relativePath":"events/using-events-to-extend-business-logic.md","filePath":"events/using-events-to-extend-business-logic.md"}`),a={name:`events/using-events-to-extend-business-logic.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="using-events-to-extend-existing-business-logic" tabindex="-1">Using Events to Extend Existing Business Logic <a class="header-anchor" href="#using-events-to-extend-existing-business-logic" aria-label="Permalink to “Using Events to Extend Existing Business Logic”">​</a></h1><p>In Business Central, developers can use events to extend existing application functionality without modifying Microsoft&#39;s base application code.</p><p>This is particularly useful when customizing standard business processes.</p><h2 id="how-it-works" tabindex="-1">How It Works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to “How It Works”">​</a></h2><p>Suppose Business Central has a standard process for creating customers.</p><p>We want to introduce additional functionality, such as sending a notification whenever a customer is created.</p><p>Instead of modifying Microsoft&#39;s customer creation logic:</p><ol><li>Identify an appropriate event published by Business Central.</li><li>Create an event subscriber in your extension.</li><li>Implement the additional business logic inside the subscriber.</li><li>Business Central executes the subscriber when the event is raised.</li></ol><h2 id="example-extending-customer-creation" tabindex="-1">Example: Extending Customer Creation <a class="header-anchor" href="#example-extending-customer-creation" aria-label="Permalink to “Example: Extending Customer Creation”">​</a></h2><p>Suppose we want to display a notification whenever a customer is inserted.</p><p>We can subscribe to the standard Customer table event:</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>codeunit 50100 CustomerExtension</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    [EventSubscriber(</span></span>
<span class="line"><span>        ObjectType::Table,</span></span>
<span class="line"><span>        Database::Customer,</span></span>
<span class="line"><span>        &#39;OnAfterInsertEvent&#39;,</span></span>
<span class="line"><span>        &#39;&#39;,</span></span>
<span class="line"><span>        false,</span></span>
<span class="line"><span>        false)]</span></span>
<span class="line"><span>    local procedure NotifyCustomerCreated(</span></span>
<span class="line"><span>        var Rec: Record Customer;</span></span>
<span class="line"><span>        RunTrigger: Boolean)</span></span>
<span class="line"><span>    begin</span></span>
<span class="line"><span>        Message(&#39;Customer %1 has been created.&#39;, Rec.Name);</span></span>
<span class="line"><span>    end;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>We haven&#39;t modified the original customer creation process.</p><p>We&#39;ve simply added our own behaviour that executes when the appropriate event occurs.</p><h2 id="why-use-events" tabindex="-1">Why Use Events? <a class="header-anchor" href="#why-use-events" aria-label="Permalink to “Why Use Events?”">​</a></h2><ul><li><strong>Upgrade compatibility:</strong> Avoid modifying Microsoft&#39;s base application, making upgrades easier.</li><li><strong>Loose coupling:</strong> The original application doesn&#39;t need to know about your extension&#39;s additional functionality.</li><li><strong>Maintainability:</strong> Custom logic remains separate from standard application logic.</li><li><strong>Extensibility:</strong> Multiple extensions can respond to the same event.</li></ul><h2 id="important-considerations" tabindex="-1">Important Considerations <a class="header-anchor" href="#important-considerations" aria-label="Permalink to “Important Considerations”">​</a></h2><ul><li>Choose the appropriate event for the business operation.</li><li>Prefer standard Business Central events where suitable.</li><li>Avoid placing excessive or unrelated logic inside subscribers.</li><li>Be careful with <code>OnBefore</code> and <code>OnAfter</code> events, especially when modifying records or influencing business processes.</li><li>Avoid introducing unnecessary dependencies between extensions.</li></ul><h2 id="key-takeaway" tabindex="-1">Key Takeaway <a class="header-anchor" href="#key-takeaway" aria-label="Permalink to “Key Takeaway”">​</a></h2><p>Events allow developers to extend existing Business Central business logic by subscribing to published events and executing additional functionality without directly modifying the original application code.</p>`,20)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};